INSERT INTO afastamento.cid (codigo_cid, nome_doenca, descricao, capitulo)
VALUES
    ('1G60', 'Alguns outros transtornos de origem infecciosa', 'Diversos transtornos de origem infecciosa não classificáveis ​​em outra parte, incluindo aquelas causadas ​​por algas e oomicetos.', '01'),
