    ('9A26', 'Deformidade combinada de osso e tecido mole de órbita', 'Deformidade combinada de osso e tecido mole de órbita', '09'),
    ('9A2Y', 'Outros transtornos especificados da órbita', 'Outros transtornos especificados da órbita', '09'),
