    ('JA66.0', 'Achados hematológicos anormais do rastreamento ["screening"] pré-natal da mãe', 'Sinal caracterizado por uma anormalidade hematológica detectada durante triagem no pré-natal da mãe.', '18'),
    ('JA66.1', 'Achados bioquímicos anormais do rastreamento ["screening"] pré-natal da mãe', 'Sinal caracterizado por uma anormalidade bioquímica detectada durante triagem pré-natal da mãe.', '18'),
