    ('KA21.47', 'Recém-nascido pré-termo, idade gestacional de 35 semanas completas', 'Recém-nascido pré-termo, idade gestacional de 35 semanas e 0 dias a 35 semanas e 6 dias', '19'),
    ('KA21.48', 'Recém-nascido pré-termo, idade gestacional de 36 semanas completas', 'Recém-nascido pré-termo, idade gestacional de 36 semanas e 0 dias a 36 semanas e 6 dias', '19'),
